 workspace:{problem:'',known:'',unknown:'',constraints:'',variables:'',relation:'',model:'',evidence:'',next:''},questionTree:['','','','',''],graphConfig:{a:'',b:'',c:'',min:'',max:'',note:''},checklist:{},
 versions:[],evidence:[],viewpoints:[],firstThoughts:{},helpHistory:[],helpThreads:[],activeHelpThread:null,debate:[],product:{audience:'',title:'',claim:'',limitations:'',rehearsal:'',rehearsalChecks:[false,false,false,false],reflection:''},
 teacherConfig:{mathTopic:'',standard:'',finalProduct:'',stages:'',knowledge:[],staticHints:['先标出已知、未知和约束。','把当前卡点拆成一个可检验的子问题。','选择一步计算、测量或反例进行核验。']},
