async function api(path,options={}){const init={credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options};const res=await fetch(path,init);const type=res.headers.get('content-type')||'';const data=type.includes('application/json')?await res.json():null;if(!res.ok)throw new Error((data&&data.error)||`请求失败（${res.status}）`);return data}
function load(){return _state||defaultState()}
const draftKey=()=>`mpt:draft:${_session.role||'guest'}:${_session.groupId||'class'}:${location.pathname}${location.search}`;
