function clearDraft(){try{localStorage.removeItem(draftKey())}catch(_){}}
function restoreDraft(){try{const raw=localStorage.getItem(draftKey());if(!raw)return;const saved=JSON.parse(raw);if(!saved||Date.now()-Number(saved.time||0)>86400000)return clearDraft();draftFields().forEach((el,i)=>{const item=saved.fields?.[i];if(!item)return;if(el.type==='checkbox'||el.type==='radio')el.checked=Boolean(item.checked);else if(typeof item.value==='string')el.value=item.value})}catch(_){} }
function installDraftAutosave(){const fields=draftFields();if(!fields.length)return;let timer;const persist=()=>{try{localStorage.setItem(draftKey(),JSON.stringify({time:Date.now(),fields:fields.map(el=>el.type==='checkbox'||el.type==='radio'?{checked:el.checked}:{value:el.value})}))}catch(_){}};const schedule=()=>{clearTimeout(timer);timer=setTimeout(persist,250)};fields.forEach(el=>{el.addEventListener('input',schedule);el.addEventListener('change',schedule)});window.addEventListener('beforeunload',persist,{once:true});}
function save(s){_state=s;const body=JSON.stringify({state:deepClone(s)});_saveQueue=_saveQueue.then(()=>api('/api/state',{method:'PUT',keepalive:true,body})).then(()=>clearDraft()).catch(e=>toast(`保存失败：${e.message}`));return _saveQueue}
async function refreshState(){const data=await api('/api/state');_state=Object.assign(defaultState(),data.state||{});return _state}
async function reset(){try{await api('/api/state/reset',{method:'POST',body:'{}'});location.reload()}catch(e){toast(e.message)}}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'})}finally{location.href='/?current'}}
function event(s,type,data='',group='',stage=s.currentStage){const actual=group||`G${String(s.groupId||1).padStart(2,'0')}`;s.events.push({ts:iso(),type,group:actual,stage,data});if(s.events.length>120)s.events=s.events.slice(-120);}
function audit(s,actor,action,detail){s.audit.unshift({time:now(),actor,action,detail});if(s.audit.length>80)s.audit=s.audit.slice(0,80)}
function toast(msg){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el)}el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2200)}
function esc(x){return String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function safeCalculate(source){const text=String(source).replace(/\s+/g,'');let at=0;const number=()=>{const start=at;while(/[0-9.]/.test(text[at]||''))at++;if(start===at)throw new Error('需要数字');const value=Number(text.slice(start,at));if(!Number.isFinite(value))throw new Error('数字无效');return value};const factor=()=>{if(text[at]==='('){at++;const value=expression();if(text[at]!==')')throw new Error('括号不匹配');at++;return value}if(text[at]==='-'){at++;return -factor()}return number()};const term=()=>{let value=factor();while(text[at]==='*'||text[at]==='/'){const op=text[at++],right=factor();if(op==='/'&&right===0)throw new Error('不能除以0');value=op==='*'?value*right:value/right}return value};const expression=()=>{let value=term();while(text[at]==='+'||text[at]==='-'){const op=text[at++],right=term();value=op==='+'?value+right:value-right}return value};const result=expression();if(at!==text.length||!Number.isFinite(result))throw new Error('表达式无效');return result}
function stage(n){return STAGES[n-1]}
function stageStrip(){const s=load();return `<div class="stage-strip">${STAGES.map(x=>`<a class="stage-card ${s.stageSubmitted[x.n]?'done':''} ${s.currentStage===x.n?'current':''}" href="stage${x.n}.html"><div class="stage-no">阶段 ${x.n}</div><div class="stage-name">${x.name}</div><div class="stage-state">${s.stageSubmitted[x.n]?'已提交':s.currentStage===x.n?(s.stagePaused?'已暂停':'当前进行'):x.n<s.currentStage?'已开放':'待进入'}</div><div class="stage-output">${x.output}</div></a>`).join('')}</div>`}
function btn(label,cls='',id='',extra=''){return `<button class="btn ${cls}" ${id?`id="${id}"`:''} ${extra}>${label}</button>`}
function badge(t,cls=''){return `<span class="badge ${cls}">${t}</span>`}
function studentNav(active){const s=load(),h=hintStatus(s);return `<aside class="sidebar"><div class="nav-label">课堂导航</div><nav class="nav"><a class="${active==='home'?'active':''}" href="dashboard.html">▸ 课堂首页</a>${STAGES.map(x=>`<a class="sub ${active===`s${x.n}`?'active':''}" href="stage${x.n}.html">${x.n} ${x.name}</a>`).join('')}<div class="sep"></div><a class="${active==='workspace'?'active':''}" href="workspace.html">▸ 共享工作区</a><a class="${active==='group'?'active':''}" href="group.html">▸ 小组协作与角色</a><a class="${active==='help'?'active':''}" href="help.html">▸ 提示与求助 <span class="count">${h.level} ${h.used}/${h.quota}</span></a><a class="${active==='history'?'active':''}" href="history.html">▸ 过程与版本回看</a><div class="nav-label">系统说明</div><a class="${active==='gov'?'active':''}" href="governance.html">▸ 数据使用说明</a><a href="/?current">▸ 返回登录入口</a></nav></aside>`}
function teacherNav(active){const links=[['home','课堂总览','dashboard.html'],['project','项目与支架配置','project.html'],['stages','课堂阶段控制','stages.html'],['groups','小组态势','groups.html'],['queue','教师升级队列','queue.html'],['broadcast','广播与共性澄清','broadcast.html'],['eval','成果评价','evaluation.html'],['report','课后总结','report.html'],['export','课堂数据导出','export.html'],['gov','运行与数据治理','governance.html'],...(_session.isAdmin?[['access','账号与访问管理','access.html']]:[])];const s=load();return `<aside class="sidebar"><div class="nav-label">课堂导航</div><nav class="nav">${links.map(x=>`<a class="${active===x[0]?'active':''}" href="${x[2]}">▸ ${x[1]}${x[0]==='queue'?`<span class="count">${s.queue.filter(q=>!q.resolved).length}</span>`:''}</a>`).join('')}<div class="nav-label">系统</div><a href="/?current">▸ 返回登录入口</a></nav></aside>`}
function topbar(role){const s=load();const student=role==='student',className=s.className||'未填写班级名称',teacherName=_session.username||'教师',memberCount=Array.isArray(s.members)?s.members.filter(Boolean).length:0;return `<header class="topbar">${brandLockup()}<div class="top-actions"><span class="pill"><i class="status-dot ${s.aiOpen?'on':'off'}"></i>AI${s.aiOpen?'开放':'暂停'}</span><span class="pill">${student?`${className} · ${s.groupId}组${memberCount?` · ${memberCount}人`:''} · 小组端`:`${className} · ${teacherName} · 教师总控端`}</span><button class="btn sm" data-logout>退出登录</button></div></header>`}
